const s=wb.getWorksheet('Sheet1');
s.getRange('K2:K6').setFormula('=INDEX($B$1:$H$1,MATCH(TEXT(J2,"dd/mm/yyyy")&"*",B2:H2,0))');
const out=[];
for(let r=2;r<=6;r++){const c=s.getRange('K'+r).getCell();
 const alt=await wb.evaluate(`=INDEX(Sheet1!$B$1:$H$1,MATCH(Sheet1!J${r},Sheet1!C${r}:I${r},0))`);
 out.push(['K'+r,c.getFormula?.(),c.getValue(),c.getText(),'alt:',alt].join(' | '));}
out.push(String(await wb.evaluate('=VALUE(REPLACE("11/05/1999 -WoodWork",11,500,""))')));
out.join('\n')

